// Market-data layer: the ONLY module that knows where prices come from.
// UI components consume `useMarket()` (store.jsx) and render `SourceBadge` (app/shared.jsx), never raw feeds.
//
// Each instrument row carries `data_source`:
//   'simulated' — generated by EQOTO's demo engine (random walk). Never a market quote.
//   'licensed'  — written by a licensed provider through the service-role `ingest_quotes` function.
//                 See docs/INTEGRATIONS.md. No licensed provider is connected in this repository.
// Orders in EQOTO are always paper trades against simulated balances, regardless of the price source.
import { db, getSession, rpc } from './supabase'

export const PROVIDERS = {
  simulated: { id: 'simulated', label: 'Simulated', live: false, note: 'Demo price generated by EQOTO. Not a live market quote and not executable at any broker.' },
  licensed: { id: 'licensed', label: 'Licensed feed', live: true, note: 'Quote supplied by a licensed market-data provider. Orders remain paper trades.' },
}
export const sourceOf = (ins) => PROVIDERS[ins?.data_source] || PROVIDERS.simulated
/** A licensed quote older than this is shown as stale rather than live. */
export const STALE_MS = 20 * 60 * 1000
export const isStale = (ins) => sourceOf(ins).live && ins?.quote_at && Date.now() - new Date(ins.quote_at).getTime() > STALE_MS

export const fetchInstruments = () => db.from('instruments').select('*').order('symbol')

export async function fetchSparks() {
  const rows = await rpc('price_sparks')
  return Object.fromEntries((rows || []).map((r) => [r.symbol, (r.prices || []).map(Number)]))
}

const DAYS = { '1D': 1, '1W': 7, '1M': 30, '3M': 90 }
const cache = new Map()
/** Down-sampled price history for charts. range: 1D | 1W | 1M | 3M */
export async function fetchSeries(symbol, range = '1M') {
  const key = `${symbol}:${range}`
  const hit = cache.get(key)
  if (hit && Date.now() - hit.at < 20000) return hit.rows
  const rows = await rpc('price_series', { p_symbol: symbol, p_days: DAYS[range] || 30, p_points: 160 })
  const out = (rows || []).map((r) => ({ t: new Date(r.ts).getTime(), v: Number(r.price) }))
  cache.set(key, { at: Date.now(), rows: out })
  return out
}

export const fetchDailyCloses = (symbols, days = 30) => (symbols.length ? rpc('daily_closes', { p_symbols: symbols, p_days: days }) : [])

/** Advances the built-in simulation (server-throttled). A no-op for licensed instruments. */
export const tickSimulation = () => (getSession() ? rpc('tick_prices').catch(() => {}) : Promise.resolve())
